  const normalized = decodeHtml(html.replace(/\\\//g, "/").replace(/\\u0026/gi, "&"));
  for (const m of normalized.matchAll(/https?:\/\/[^"'\s<>\\]+\.(?:m3u8|mp4)(?:[?#][^"'\s<>\\]*)?/gi)) {
    addStream(m[0], "Direct", pageUrl);
  }
